nodes.statement:
Let $n\in\mbox{${\mathbb N}$}, n\geq 2$ and let $A_1, A_2, \ldots, A_n$ be selfadjoint operators in $\mathcal{H}$ with scalar-valued spectral measures $\lambda_{A_1}, \ldots, \lambda_{A_n}$. We let
\begin{equation*}
\Gamma^{A_1,A_2, \ldots, A_n} : L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n}) \rightarrow \mathcal{B}_{n-1}(\mathcal{S}^2(\mathcal{H}))
\end{equation*}
to be the unique linear map such that for any $f_i \in L^{\infty}(\lambda_{A_i}), i=1, \ldots, n$ and for any $X_1, \ldots, X_{n-1} \in \mathcal{S}^2(\mathcal{H})$,
\begin{align} \left[\Gamma^{A_1,A_2, \ldots, A_n}(f_1\otimes\cdots\otimes f_n)\right]
& (X_1,\ldots, X_{n-1})\\ \nonumber
& =f_1(A_1)X_1f_2(A_2) \cdots f_{n-1}(A_{n-1})X_{n-1}f_n(A_n).
\end{align}

It is well-known that $f^{[n]}$ is symmetric under permutation of its arguments. Therefore, for all $1 \leq i \leq n$ and for all $x_0, \ldots, x_n \in \mathbb{R}$,
\begin{align*}
&f^{[n]} (x_0,x_1,\ldots,x_n) \\
& \ \ \ \ = \dfrac{f^{[n-1]}(x_0,\ldots,x_{i-1}, x_{i+1}, \ldots,x_n) - f^{[n-1]}(x_0,\ldots,x_{i-2}. x_{i},x_{i+1},\ldots,x_n)}{x_{i-1}-x_i}
\end{align*}
 if $x_{i-1} \neq x_i$ and
$$
f^{[n]} (x_0,x_1,\ldots,x_n) = \partial_i f^{[n-1]}(x_1,\ldots,x_n)
$$
if $x_{i-1}=x_i.$

also_stated_at:
Let $1<p<\infty$, $n\in \mathbb{N}$ and let $K=K^* \in \mathcal{S}^p(\mathcal{H})$. We prove that if $f$ is $n$-times differentiable on $\mathbb{R}$ with bounded (possibly discontinuous) $n$th derivative $f^{(n)}$, then for any bounded selfadjoint operator $A$, $\varphi$ is $n$-times differentiable on $\mathbb{R}$ and for any $1\leq k\leq n$, 
\begin{equation}\label{diffenrentialintro}
\dfrac{1}{k!} \varphi^{(k)}(t) = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f^{[k]}) \right] (K, \ldots, K), t\in \mathbb{R}.
\end{equation}

nodes.statement:
By $w^*$-continuity of multiple operator integrals and the assumptions of the Lemma we have
\begin{align*}
& | {\mathrm{Tr}\,}(\left[\Gamma^{A_1,A_2, \ldots, A_n}(\varphi)\right](X_1,\ldots,X_{n-1})Y)| \\
& = \liminf_k | {\mathrm{Tr}\,}(\left[\Gamma^{A_1,A_2, \ldots, A_n}(\varphi_k)\right](X_1,\ldots,X_{n-1})Y)| \\
& \leq \liminf_k \| \left[\Gamma^{A_1,A_2, \ldots, A_n}(\varphi_k)\right](X_1,\ldots,X_{n-1}) \|_{\alpha} \|Y\|_{\alpha'} \\
& \leq \gamma \|X_1\|_{\alpha_1} \cdots \|X_{n-1}\|_{\alpha_{n-1}}.
\end{align*}
This inequality holds true for any finite-rank operator $Y$ on $\mathcal{H}$ with $\|Y\|_{\alpha'} \leq 1$, hence
\begin{equation} \| \left[\Gamma^{A_1,A_2, \ldots, A_n}(\varphi)\right](X_1,\ldots,X_{n-1}) \|_{\alpha} \leq \gamma \|X_1\|_{\alpha_1} \cdots \|X_n\|_{\alpha_{n-1}}.
\end{equation}

Since $\left(\Gamma^{A_1, \ldots, A_n}(\varphi_k) \right)_{k\geq 1} \subset \mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})$ is bounded, we can set $C' := \sup_j \|\Gamma^{A_1, \ldots, A_n}(\varphi_j)\|_{\mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})}$. By Remark $\ref{Ineqmulti}$, there exists a constant $C > 0$ depending only on $n, C', \|X_1\|_{\alpha_1}, \ldots, \|X_{n-1}\|_{\alpha_{n-1}}$ such that, for any $k\geq 1$,
\begin{equation} \| \Gamma_{k,X} - \tilde{\Gamma}_{k,X} \|_p \leq C \epsilon \ \ \text{and} \ \ \| \Gamma_{X} - \tilde{\Gamma}_{X} \|_p \leq C \epsilon.
\end{equation}

By the first part of the proof, there exists $k_0 \in \mathbb{N}$ such that for any $k\geq k_0$,
\begin{equation} | {\mathrm{Tr}\,}((\tilde{\Gamma}_X - \tilde{\Gamma}_{k,X})Y)| < \epsilon.
\end{equation}

In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes L^{\infty}(\lambda_{A_{j+1}})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \lambda_{A_{j+1}})$. Fix $s\in S$ and assume first that $\phi_{1,s} = f_1 \otimes \cdots \otimes f_n$. By the previous computation, we have, for any $t\in T$,
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_{2,t}})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_{2,t})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n).
\end{split}
\end{align}
where $\widetilde{\phi_{2,t}}$ is defined as in \eqref{fortilde}.

By the $w^*$-continuity of $\Gamma^{A_j, A_{j+1}}$, we get that the right-hand side of \eqref{for1} converges, in the $w^*$-topology of $\mathcal{S}^2(\mathcal{H})$, to
\begin{align*}
& f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}

Indeed, let $g\in L^1(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. Then, writing $\Omega = \sigma(A_1) \times \cdots \times \sigma(A_n)$, we have, by Fubini's theorem,
\begin{align*}
& \int_{\Omega} \phi_{1,s} \widetilde{\phi_{2,t}} ~ g \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& = \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \left( \int_{\prod_{i \neq j,j+1} \sigma(A_i)} \phi_{1,s} g \ \prod_{i \neq j,j+1}\text{d}\lambda_{A_j} \right) \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}} \\
& := \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}.
\end{align*}

By Fubini's theorem, we have the inequality
\begin{align*}
\int_{\sigma(A_j) \times \sigma(A_{j+1})} | \psi_s | \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}
& \leq \int_{\Omega} | \phi_{1,s} g | \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& \leq \| \phi_{1,s} \|_{\infty} \| g\|_{1},
\end{align*}
which shows that $\psi_s \in L^1(\lambda_{A_j} \times \lambda_{A_{j+1}})$.

By $w^*$-continuity of multiple operator integrals, we have, taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for1},
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{split}
\end{align}

Note that, by linearity, this equality holds true whenever $\phi_{1,s} \in L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n}).$ Since $(\phi_{1,s} \widetilde{\phi_2})_{s\in S}$ $w^*$-converges to $\phi_1 \widetilde{\phi_2}$ we have, by taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for2},
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}

Assume now that $1\leq p < \infty$ and let $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. By assumption, there exist $A_p, B_p >0$ such that 
\begin{align} \begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p \| \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) \|_p \|K_{j+1}\|_p \ldots \| K_{n-1}\|_p \\
& \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{split}
\end{align}

Since for all $1\leq i \leq n-1, K_i \in \mathcal{S}^2(\mathcal{H})$, equality \eqref{fortildeeq} holds and we deduce the inequality
\begin{align} \left\| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \right\|_p  \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{align}

In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_j})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_j})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \cdots \times \lambda_{A_n})$. For any $s \in S$ and any $t\in T$, we have
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \phi_{2,t} \right] (K_1, \ldots, K_{n-1}) \\
& \ \ \ \ = \left[ \Gamma^{A_1, \ldots, A_j}(\phi_{1,s})\right] (K_1, \ldots, K_{j-1}) \left[ \Gamma^{A_j, \ldots, A_n}(\phi_{2,t})\right] (K_j, \ldots, K_{n-1}).
\end{split}
\end{align}

Now let $1 \leq p <\infty$ and $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. Then equality \eqref{simplificationsepid} holds and by assumption, there exist $A_p, B_p >0$ such that
\begin{align*}
\begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi)\right] (K_1, \ldots, K_{n-1})\|_p \\
& \leq \| \left[ \Gamma^{A_1, \ldots, A_j}(\phi_1)\right] (K_1, \ldots, K_{j-1}) \|_p \| \left[ \Gamma^{A_j, \ldots, A_n}(\phi_2)\right] (K_j, \ldots, K_{n-1}) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p ~ B_p \|K_j \|_p \ldots \|K_{n+1}\|_p,
\end{split}
\end{align*}
which shows that $\Gamma^{A_1, \ldots, A_n}(\phi) \in \mathcal{B}_{n-1}(\mathcal{S}^p(\mathcal{H}))$.

Assume that $2\leq j \leq n-1$. We first assume that $p=2$. If $\phi = f_1 \otimes \cdots \otimes f_{j-1} \otimes f_{j+1} \otimes \cdots \otimes f_n, f_i \in L^{\infty}(\lambda_{A_i}), 1\leq i\neq j \leq n$, we have
\begin{equation*}
\widetilde{\phi} = f_1 \otimes \cdots \otimes f_{j-1} \otimes 1 \otimes f_{j+1} \otimes \cdots \otimes f_n
\end{equation*}
so that
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\widetilde{\phi})\right] (K_1, \ldots, K_{n-1}) \\
&  = f_1(A_1)K_1 \ldots K_{j-2}f_{j-1}(A_{j-1}) K_{j-1} K_j f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_{j-1}, A_{j+1}, \ldots, A_n}(\phi)\right] \left(K_1, \ldots, K_{j-1}, K_j K_{j+1}, K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}

Let $1 \leq j \leq n$. First note that we have the following equality: for any $(x_0, \ldots, x_n) \in \mathbb{R}^{n+1}$,
\begin{align} \begin{split}
& f^{[n]}(x_0, \ldots, x_n).(x_{j-1} - x_j) \\
& \ \ \ = f^{[n-1]}(x_0,\ldots,x_{j-1}, x_{j+1}, \ldots,x_n) - f^{[n-1]}(x_0,\ldots,x_{j-2}, x_{j},x_{j+1},\ldots,x_n).
\end{split}
\end{align}

Applying the operator $\left[\Gamma_{B,A}(\cdot)\right](K_1, \ldots, K_{j-1}, X, K_j, \ldots K_{n-1})$ to \eqref{eqfunc} gives, by Lemma $\ref{simplification1}$ and Lemma $\ref{simplification2}$,
\begin{align} \begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, Bp_k(B)Xp_k(A) - p_k(B)Xp_k(A)A, K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)Xp_k(A) K_j, K_{j+1} \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)Xp_k(A) K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}
\end{align}

Let $(P_i)_k$ be an increasing sequence of finite rank projections converging strongly to the identity and such that
\begin{equation} BP_i - P_iB \underset{i \to \infty}{\longrightarrow} 0 \ \text{in} \ \mathcal{S}^p(\mathcal{H}).
\end{equation}
As explained before the statement of the Proposition, such sequence exists. We apply equality \eqref{eqfunc2} to $X=P_i$ and we obtain, for any $i\geq 1$,
\begin{align} \begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, Bp_k(B)P_ip_k(A) - p_k(B)P_ip_k(A)A, K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)P_ip_k(A) K_j, K_{j+1}, \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)P_ip_k(A)K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}
\end{align}

Note that for any $K \in \mathcal{S}^p(\mathcal{H}), KP_i \to K$ and $P_iK\to K$ in $\mathcal{S}^p(\mathcal{H})$, as $i$ goes to $\infty$. This implies that $p_k(B)P_ip_k(A) K_j \to p_k(B)p_k(A) K_j$ and that $p_k(B)P_ip_k(A)K_{j-1} \to p_k(B)p_k(A)K_{j-1}$ as $i$ goes to $\infty$. By continuity of multiple operator integrals stated in Theorem $\ref{BddnessMOI}$, this implies that the right-hand side of \eqref{eqfunc3} converges in $\mathcal{S}^p(\mathcal{H})$ to
\begin{align*}
&\left[ \Gamma_B (f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)p_k(A) K_j, K_{j+1}, \ldots, K_{n-1})\\
& - \left[ \Gamma_A (f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)p_k(A)K_{j-1}, K_j \ldots, K_{n-1}).
\end{align*}

In the case when $j=1$, the right-hand side of \eqref{eqfunc2} is replaced by
\begin{align*}
& \left[ \Gamma_B (f^{[n-1]})\right](p_k(B)Xp_k(A)K_1, K_2, \ldots, K_{n-1})\\
& \ \ \ \ - p_k(B)Xp_k(A)\left[ \Gamma_A (f^{[n-1]})\right](K_1,\ldots, K_{n-1})
\end{align*}
and when $j=n$, the right-hand side is replaced by
\begin{align*}
& \left[ \Gamma_B (f^{[n-1]})\right](K_1, \ldots, K_{n-1})p_k(B)Xp_k(A)\\
& \ \ \ \ - \left[ \Gamma_A (f^{[n-1]})\right](K_1,\ldots, K_{n-2}, p_k(B)Xp_k(A)K_{n-1}).
\end{align*}
We then apply the same reasonning as before to obtain the result.

Note that for an elementary tensor $g = g_1 \otimes \cdots \otimes g_{n+1} \in \text{Bor}(\mathbb{R}) \otimes \cdots \otimes \text{Bor}(\mathbb{R})$, we have
\begin{align*}
\left[ \Gamma^{A, \ldots, A}(g) \right] (Z_1, \ldots, Z_n)
& = g_1(A)Z_1g_2(A)\ldots g_n(A)Z_ng_{n+1}(A) \\
& = g_1(A)\ldots g_{n+1}(A) Z_1 \ldots Z_n \\
& = \tilde{g}(A) Z_1 \ldots Z_n.
\end{align*}
By linearity, this implies that for any $j \geq 1$,
\begin{equation} \left[ \Gamma^{A, \ldots, A}(Q^k_j) \right] (Z_1, \ldots, Z_n) = \tilde{Q}^k_j(A)Z_1\ldots Z_n.
\end{equation}

Note that $(\tilde{Q}^k_j)_{j\geq 1}$ converges uniformly to $\tilde{\phi}_k$ on $\sigma(A)$. Hence, $\tilde{Q}^k_j(A)$ converges to $\tilde{\psi}_k(A)$ in $\mathcal{B}(\mathcal{H})$ so that the right-hand side of \eqref{eqcomm0} converges in $\mathcal{S}^p(\mathcal{H})$ to $\tilde{\psi}_k(A)Z_1\ldots Z_n$. By taking the limit on $j$ in \eqref{eqcomm0} we get
\begin{equation} \left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) = \tilde{\psi}_k(A)Z_1\ldots Z_n.
\end{equation}

We have the following decomposition
\begin{align*}
&\psi(t) - \psi(0) \\
& = \sum_{k=1}^j \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k-1}}(f^{[n-1]}) - \Gamma^{(A+tK)^{j-k},(A)^{n-j+k}}(f^{[n-1]}) \right](X_1, \ldots, X_{n-1}).
\end{align*}

For any $1\leq k\leq j$, we have, by Proposition $\ref{simplification0}$,
\begin{align*}
& \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k-1}}(f^{[n-1]}) - \Gamma^{(A+tK)^{j-k},(A)^{n-j+k}}(f^{[n-1]}) \right](X_1, \ldots, X_{n-1}) \\
& = t \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k}}(f^{[n]}) \right](X_1, \ldots, X_{j-k}, K, X_{j-k+1}, \ldots, X_{n-1}),
\end{align*}
from which we deduce \eqref{simplification5eq}.

By Lemma $\ref{simplification5}$ we have
\begin{align*}
\psi(t) - \tilde{\psi}(t) = t \sum_{k=1}^{n} \left[ \Gamma^{(A+tK)^{n-k+1}, (A+tK_0)^k}(f^{[n]})\right]((K)^{n-k}, K-K_0, (K)^{k-1}).
\end{align*}
Hence, by Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $\beta>0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that, for any $t\in \mathbb{R}$
\begin{equation} \| \psi(t) - \tilde{\psi}(t) \|_p \leq n \beta |t| \epsilon.
\end{equation}

Let also $\gamma>0$ be a constant depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that
\begin{equation} \| \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K) - \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p \leq \gamma \epsilon.
\end{equation}

Let $\epsilon > 0$. By assumption, there exists $\mu_1 > 0$ such that for any $|t| < \mu_1$,
\begin{equation} \| \tilde{\psi}(t) - \tilde{\psi}(0) - t \tilde{\psi}'(0) \|_p \leq |t| \epsilon.
\end{equation}

Moreover, $\nu(0)=A$ and $\nu'(0) = K$ in $\mathcal{S}^p(\mathcal{H})$, so there exists $\mu_2 > 0$ such that for any $|t| < \mu_2$,
\begin{equation*}
\left\| \frac{(A+tK) - \mu(t)}{t} \right\|_p = \left\| \frac{\mu(t)-A}{t} -K \right\|_p \leq \epsilon.
\end{equation*}

We have, by Proposition $\ref{simplification0}$,
\begin{align*}
& \dfrac{\psi(t) - \tilde{\psi}(t)}{t}  \\
& = \dfrac{1}{t} \sum_{k=1}^n \left[ \Gamma^{(A+tK)^{n-k+1}, (\nu(t))^{k-1}}(f^{[n-1]})-\Gamma^{(A+tK)^{n-k}, (\nu(t))^k}(f^{[n-1]}) \right](K, \ldots, K) \\
& = \sum_{k=1}^{n} \left[ \Gamma^{(A+tK)^{n-k+1}, (\nu(t))^k}(f^{[n]})\right]\left( (K)^{n-k}, \frac{(A+tK) - \mu(t)}{t} , (K)^{k-1} \right).
\end{align*}
Hence, by Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $\alpha > 0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that, for any $t\in \mathbb{R}$,
\begin{equation} \| \psi(t) - \tilde{\psi}(t) \|_p \leq |t| n \alpha \epsilon.
\end{equation}

In the case $1 < p < \infty$, we approximate $Y \in \mathcal{S}^p(\mathcal{H})$ by a sequence $(Y_j)_{j\geq 1}$ of elements of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$ and then pass to the limit in the equality
\begin{align*}
&\left[\Gamma^{A+K_m, \ldots, A+K_m}(f^{[n]}) \right]((Y_j)_m, \ldots, (Y_j)_m) \\
& \ \ \ \ = \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(f^{[n]}) \right]((Y_j)_m, \ldots, (Y_j)_m)
\end{align*}
as $j \to \infty$, using the estimate in Theorem $\ref{BddnessMOI}$ and the fact that $(Y_j)_m \underset{j \to \infty}{\longrightarrow} Y_m$ in $\mathcal{S}^p(\mathcal{H})$.

We have, by Proposition $\ref{simplification0}$,
\begin{align*}
& \dfrac{\tilde{\psi}(t) - \tilde{\psi}(0)}{t}  \\
& = \dfrac{1}{t} \sum_{k=1}^n \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^{k-1}}(f^{[n-1]})-\Gamma^{(\nu(t))^{n-k}, (A)^k}(f^{[n-1]}) \right](K, \ldots, K) \\
& = \sum_{k=1}^{n} \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^k}(f^{[n]})\right]\left( (K)^{n-k}, \frac{\nu(t) - A}{t} , (K)^{k-1} \right).
\end{align*}

Note that
\begin{align*}
& \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^k}(f^{[n]})\right]\left( K,\ldots,K \right) \\
& \ \ \ \ \ \ = e^{-itY}\left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]})\right]\left((e^{itY}Ke^{-itY})^{n-k},e^{itY}K, (K)^{k-1} \right).
\end{align*}

In fact, more generally, for any $t\in \mathbb{R}$, for any $g\in \text{Bor}(\mathbb{R}^{n+1})$ such that $\Gamma^{(\nu(t))^{n-k+1}, (A)^k}(g) \in \mathcal{B}_n(\mathcal{S}^p)$ and any $X \in  \mathcal{S}^p(\mathcal{H})$, we have
\begin{align*}
& \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^k}(g)\right]\left(X, \ldots, X \right) \\
& \ \ \ \ \ \ = e^{-itY}\left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(g)\right]\left((e^{itY}Xe^{-itY})^{n-k},e^{itY}X, (X)^{k-1} \right).
\end{align*}
Indeed, when $g$ is an element of $\text{Bor}(\mathbb{R}) \otimes \cdots \otimes \text{Bor}(\mathbb{R})$, this equality is a consequence of the fact that for any $h \in \text{Bor}(\mathbb{R})$, $h(e^{-itY}(A+tZ)e^{itY}) = e^{-itY}h(A+tZ)e^{itY}$. Hence, if $p=2$, the general case follows from the $w^*$-continuity of multiple operator integrals. If $1<p<\infty$, we approximate $X\in \mathcal{S}^p(\mathcal{H})$ by elements of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. Details are left to the reader.

Now, when $t$ goes to $0$, $e^{-itY} \to 1$ in $\mathcal{B}(\mathcal{H})$ so that $e^{itY}Ke^{-itY}, e^{itY}K \to K$ in $\mathcal{S}^p(\mathcal{H})$. Hence, by uniform boundedness of $\Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]}) \in \mathcal{B}_n(\mathcal{S}^p), t\in \mathbb{R}$, we have that if one of those limits exists, so does the second one and then
\begin{align*}
& ~ \ \ \ \underset{t \to 0}{\lim} \ e^{-itY}\left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]})\right]\left((e^{itY}Ke^{-itY})^{n-k},e^{itY}K, (K)^{k-1} \right) \\
& = \underset{t \to 0}{\lim} \ \left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]})\right]\left(K, \ldots, K \right).
\end{align*}

Hence,
\begin{align*}
\xi(t) 
& = \sum_{k=1}^{n} \left[ \Gamma_k(t) \right] (Z, \ldots, Z) \\
& + \sum_{k=1}^{n} \sum_{j=1}^n \ \sum_{\substack{K_m = i[A,Y] \\\text{or} \ K_m=Z, \\ 1 \leq m \leq n-1}} i \left[ \Gamma_k(t) \right] (K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1}).
\end{align*}

By Lemma $\ref{simplification5}$ and Lemma $\ref{MOIcomm}$ we have
\begin{align*}
\sum_{k=1}^{n} \left[ \Gamma_k(t) \right] (Z, \ldots, Z)
& = \dfrac{1}{t} \left[ \Gamma^{A+tZ,\ldots, A+tZ}(f^{[n-1]}) - \Gamma^{A,\ldots, A}(f^{[n-1]}) \right](Z, \ldots, Z) \\
& = \dfrac{1}{(n-1)!} \ \dfrac{f^{(n-1)}(A+tZ)-f^{(n-1)}(A) }{t} \ Z^{n-1}.
\end{align*}

Assume first that $n-k+2 \leq j \leq n$. Since $A$ and $Z$ are bounded operators, we have, by Remark $\ref{approximatebdd}$,
\begin{align*}
& \left[\Gamma_k(t)\right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1}) \\
& = \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_j, K_{j+1}, \ldots, K_{n-1}) \\
& \ \ \ - \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_{j-1}, K_j, \ldots, K_{n-1}),
\end{align*}
with a simple modification in the case $j=n$. By Lemma $\ref{simplification5}$ the latter converges, as $t$ goes to $0$, to
\begin{align*}
&\left[\Gamma^{A, \ldots, A}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_j, K_{j+1}, \ldots, K_{n-1}) \\
& - \left[\Gamma^{A, \ldots, A}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_{j-1}, K_j, \ldots, K_{n-1}),
\end{align*}
which is in turn equal to $\left[\Gamma^{A,\ldots, A}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})$.

Finally, let $I\subset \mathbb{R}$ be a bounded interval and let $1 \leq i \leq n-1$. We let $J \subset \mathbb{R}$ to be a bounded interval such that, for any $t\in I$, $\sigma(A+tK) \subset J$. There exists $f_i \in C^i(\mathbb{R})$ compactly supported such that $f_i = f$ on $J$. Then for any $t\in I$,
\begin{align*}
\dfrac{1}{k!} \varphi^{(i)}(t)
& = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}((f^{[i]})_{|J^{n+1}}) \right] (K, \ldots, K) \\
& = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f_i^{[i]}) \right] (K, \ldots, K).
\end{align*}

By Theorem $\ref{FormulaSA}$, we know that $\varphi$ is $n$-times differentiable and that for any $t\in \mathbb{R}$,
\begin{equation*}
\dfrac{1}{n!} \varphi^{(n)}(t) = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f^{[n]}) \right] (K, \ldots, K).
\end{equation*}

For $n=1$, we have, for any $(x_0,x_1)\in \mathbb{R}^2$ with $x_0 \neq x_1$,
\begin{align} \begin{split}
f^{[1]}(x_0,x_1)g(x_0)g(x_1)
& = \dfrac{g(x_1)(gf)(x_0) - (gf)(x_1) g(x_0)}{x_0 - x_1} \\
& = \dfrac{g(x_1)(gf)(x_0) - g(x_1)(gf)(x_1)}{x_0 - x_1} \\
& \ \ \ \ + \dfrac{(gf)(x_1)g(x_1) - (gf)(x_1) g(x_0)}{x_0 - x_1} \\
& = g(x_1) (gf)^{[1]}(x_0,x_1) - (gf)(x_1)g^{[1]}(x_0,x_1).
\end{split}
\end{align}
By continuity, this equality holds true for any $x_0,x_1 \in \mathbb{R}$. Hence, by Lemma $\ref{simplification1}$, we have, for any $t\in \mathbb{R}$ and any $X\in \mathcal{S}^p(\mathcal{H})$,
\begin{align*}
& \varphi_{k,X}^1(t) \\
& = \left[ \Gamma^{A+tK, A+tK}((gf)^{[1]}) \right](Xg(A+tK)) - \left[ \Gamma^{A+tK, A+tK}(g^{[1]}) \right](X(gf)(A+tK)).
\end{align*}

As explained in the first part of the proof, the mappings $t\in \mathbb{R} \mapsto Xg(A+tK) \in \mathcal{S}^p(\mathcal{H})$ and $t\in \mathbb{R} \mapsto X(gf)(A+tK) \in \mathcal{S}^p(\mathcal{H})$ are continuous in $0$. Note that $g', (gf)' \in C_0(\mathbb{R})$ so that, by continuity of the map defined in \eqref{casefnC0} and the uniform boundedness of the mappings $\Gamma^{A+tK, A+tK}((gf)^{[1]}), \Gamma^{A+tK, A+tK}(g^{[1]}), t\in \mathbb{R}$, we get that
\begin{align*}
\underset{t\to 0}{\lim} ~ \varphi_{k,X}^1(t) = \left[ \Gamma^{A, A}((gf)^{[1]}) \right](Xg(A)) - \left[ \Gamma^{A, A}(g^{[1]}) \right](X(gf)(A)) = \varphi_{k,X}^1(0),
\end{align*}
so that $\varphi_{k,X}^1$ is continuous in $0$.

Assume now that we have \eqref{recfng} at the order $n$ and show that it still holds true at the order $n+1$. We have
\begin{align} \begin{split}
& f^{[n+1]}(x_0,\ldots, x_{n+1})g(x_0) \\
& = \dfrac{f^{[n]}(x_0, x_2, \ldots, x_{n+1})g(x_0) - f^{[n]}(x_1,\ldots, x_{n+1})g(x_1)}{x_0-x_1} \\
& \ \ \ \ + \dfrac{f^{[n]}(x_1,\ldots, x_{n+1})g(x_1) - f^{[n]}(x_1,\ldots, x_{n+1})g(x_0)}{x_0-x_1} \\
& = \dfrac{f^{[n]}(x_0, x_2, \ldots, x_{n+1})g(x_0) - f^{[n]}(x_1,\ldots, x_{n+1})g(x_1)}{x_0-x_1} \\
& \ \ \ \ - g^{[1]}(x_0,x_1) f^{[n]}(x_1,\ldots, x_{n+1}).
\end{split}
\end{align}

Let $(x_0, \ldots, x_n)\in \mathbb{R}^{n+1}$. We multiply Formula \eqref{recfng} by $g(x_n)$ and we get
\begin{align*}
f^{[n]}G_k^n(x_0, \ldots, x_n) 
& = g(x_n)(gf)^{[n]}(x_0, \ldots, x_n) - (gf)(x_n) g^{[n]}(x_0,\ldots, x_n) \\
& \ \ \ - g(x_n)\sum_{l=1}^{n-1} g^{[l]}(x_0, \ldots, x_l)f^{[n-l]}(x_{l} ,\ldots, x_n).
\end{align*}
